    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "We start with the market buzz and local life, all on foot from the centre.",
      "note_about": "San Pedro Market"
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short stroll away, and a sweet little museum for a slower morning.",
      "note_about": "ChocoMuseo"
    },
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "The plaza is the heart of the old town, perfect for photos and people-watching.",
      "note_about": "Plaza de Armas"
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "A cheap and cheerful lunch just around the corner from the plaza.",
      "note_about": "La Bodega 138"
