    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "The cathedral keeps us close to the centre and adds a bit of history.",
      "note_about": "Cusco Cathedral"
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner is a short walk from the cathedral, with local flavours to end the day.",
      "note_about": "Pachapapa"
    }
  ]
